    content:
      '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 600 750"><defs>\n    <linearGradient id="bg" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fbfaf6"/><stop offset="1" stop-color="#ece8de"/></linearGradient>\n    <radialGradient id="glow" cx="50%" cy="50%" r="50%"><stop offset="0" stop-color="#fff" stop-opacity="0.85"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></radialGradient>\n    <linearGradient id="box" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#2b2b2b"/><stop offset="1" stop-color="#0d0d0d"/></linearGradient>\n    <linearGradient id="glass" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="#fff" stop-opacity="0.55"/><stop offset="0.5" stop-color="#fff" stop-opacity="0.12"/><stop offset="1" stop-color="#fff" stop-opacity="0.4"/></linearGradient>\n    <linearGradient id="liquid" x1="0" y1="0" x2="1" y2="1"><stop offset="0" stop-color="#f5f5f0"/><stop offset="1" stop-color="#dcdcd2"/></linearGradient>\n    <linearGradient id="cap" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="#8a8a80"/><stop offset="0.35" stop-color="#ffffff" stop-opacity="0.9"/><stop offset="0.55" stop-color="#8a8a80"/><stop offset="1" stop-color="#2a2a2a"/></linearGradient>\n    <linearGradient id="collar" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="#8f7a4a"/><stop offset="0.4" stop-color="#f4e3b0"/><stop offset="1" stop-color="#6e5a30"/></linearGradient>\n    <linearGradient id="shine" x1="0" y1="0" x2="1" y2="0"><stop offset="0" stop-color="#fff" stop-opacity="0.85"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient>\n    <linearGradient id="fade" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#fff" stop-opacity="0.35"/><stop offset="1" stop-color="#fff" stop-opacity="0"/></linearGradient>\n    <filter id="soft"><feGaussianBlur stdDeviation="3"/></filter>\n    <filter id="blur18"><feGaussianBlur stdDeviation="18"/></filter>\n  </defs>\n  <rect width="600" height="750" fill="url(#bg)"/>\n  <circle cx="300" cy="300" r="260" fill="url(#glow)"/>\n  \n  <ellipse cx="300" cy="1086" rx="312" ry="12" fill="#000" opacity="0.22" filter="url(#soft)"/>\n  <rect x="211.6" y="312" width="176.8" height="74" rx="10" fill="url(#cap)"/>\n  <rect x="211.6" y="312" width="176.8" height="10" rx="5" fill="#fff" opacity="0.35"/>\n  <rect x="196" y="384" width="208" height="22" rx="4" fill="url(#collar)"/>\n  <rect x="40" y="404" width="520" height="676" rx="83.2" fill="url(#liquid)" opacity="0.18"/>\n  <clipPath id="body"><rect x="40" y="404" width="520" height="676" rx="83.2"/></clipPath>\n  <g clip-path="url(#body)">\n    <rect x="40" y="552.72" width="520" height="676" fill="url(#liquid)"/>\n    <ellipse cx="300" cy="552.72" rx="260" ry="7" fill="#fff" opacity="0.35"/>\n    <rect x="40" y="404" width="520" height="676" fill="url(#glass)"/>\n    <rect x="81.6" y="416" width="72.80000000000001" height="652" rx="36.400000000000006" fill="url(#shine)"/>\n    <rect x="466.4" y="428" width="26" height="371.8" rx="4" fill="#fff" opacity="0.45"/>\n  </g>\n  <rect x="40" y="404" width="520" height="676" rx="83.2" fill="none" stroke="#fff" stroke-opacity="0.7" stroke-width="2.5"/>\n  <rect x="128.4" y="687.9200000000001" width="343.2" height="229.84" rx="4" fill="#fffdf8" opacity="0.96"/>\n  <rect x="133.4" y="692.9200000000001" width="333.2" height="219.84" rx="2" fill="none" stroke="#b8975a" stroke-width="1.2"/>\n  <text x="300" y="809.5999999999999" font-family="Georgia, serif" font-size="104" text-anchor="middle" fill="#111">7</text>\n  <text x="300" y="856.9200000000001" font-family="Arial, sans-serif" font-size="28.6" letter-spacing="13" text-anchor="middle" fill="#111">SEVEN</text>\n  <text x="300" y="890.72" font-family="Arial, sans-serif" font-size="18.200000000000003" letter-spacing="2" text-anchor="middle" fill="#8a7a5a">EAU DE PARFUM</text>\n</svg>\n',
